python3 -c "
import inspect

class Wrapped(object):
    def __init__(self, func):
        self.func = func

    def __call__(self, *args, **kwargs):
        return self.func(*args, **kwargs)

    @property
    def __wrapped__(self):
        return self.func

func = lambda x: x
wrapped = Wrapped(func)

print('signature(wrapped):', inspect.signature(wrapped))
print('signature(Wrapped):', inspect.signature(Wrapped))
print()
print('__wrapped__ on instance:', wrapped.__wrapped__)
print('__wrapped__ on class:', getattr(Wrapped, '__wrapped__', 'NOT FOUND'))
"
